from bisect import bisect_right
from collections import defaultdict
from typing import List


class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n, m = len(word1), len(word2)
        pos = defaultdict(list)
        for idx, ch in enumerate(word1):
            pos[ch].append(idx)

        # R[j]: largest s such that word2[j:] is an exact subsequence of word1[s:]
        R = [-1] * (m + 1)
        R[m] = n
        for j in range(m - 1, -1, -1):
            if R[j + 1] <= 0:
                R[j] = -1
                continue
            lst = pos[word2[j]]
            k = bisect_right(lst, R[j + 1] - 1) - 1
            R[j] = lst[k] if k >= 0 else -1

        # T[j]: largest s such that word2[j:] is a subsequence of word1[s:]
        # with at most one mismatch
        T = [-1] * (m + 1)
        T[m] = n
        for j in range(m - 1, -1, -1):
            best = -1
            if T[j + 1] >= 1:
                lst = pos[word2[j]]
                k = bisect_right(lst, T[j + 1] - 1) - 1
                if k >= 0:
                    best = lst[k]
            if R[j + 1] >= 1:
                best = max(best, R[j + 1] - 1)
            T[j] = best

        res = []
        prev = -1
        used = False
        for j in range(m):
            lst = pos[word2[j]]
            k = bisect_right(lst, prev)
            e = lst[k] if k < len(lst) else -1

            ok_e = False
            if e != -1:
                if used:
                    ok_e = R[j + 1] >= e + 1
                else:
                    ok_e = T[j + 1] >= e + 1

            mc = -1
            if not used and prev + 1 < n and R[j + 1] >= prev + 2:
                mc = prev + 1

            if ok_e and (mc == -1 or e <= mc):
                res.append(e)
                prev = e
            elif mc != -1:
                res.append(mc)
                prev = mc
                used = True
            else:
                return []
        return res
