            R[j] = pos if pos >= 0 else -1
            # with at most one mismatch
            pos = L[j + 1] - 1
            while pos >= 0 and word1[pos] != c:
                pos -= 1
            cand = R[j + 1] - 1  # mismatch at position cand
            best = max(pos, cand)
            L[j] = best if best >= 0 else -1

        res = []
        prev = -1
        used = False
        for j in range(m):
            c = word2[j]
            p = prev + 1
            if not used:
