                    if R[j + 1] > p:
                        res.append(p)
                        prev = p
                        used = True
                    else:
                        e = p
                        while e < n and word1[e] != c:
                            e += 1
                        if e < n and L[j + 1] > e:
                            res.append(e)
                            prev = e
                        else:
                            return []
            else:
                e = p
                while e < n and word1[e] != c:
                    e += 1
                if e < n and R[j + 1] > e:
                    res.append(e)
                    prev = e
                else:
                    return []
        return res
