class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n, m = len(word1), len(word2)
        # S[k]: max start p such that word2[k:] is a subsequence of word1[p:]
        S = [-1] * (m + 1)
        S[m] = n
        p = n  # exclusive bound
        for k in range(m - 1, -1, -1):
            c = word2[k]
            q = p - 1
            while q >= 0 and word1[q] != c:
                q -= 1
            if q < 0:
                S[k] = -1
                # all earlier positions infeasible for exact matching
                for t in range(k - 1, -1, -1):
                    S[t] = -1
                break
            S[k] = q
            p = q

        def feas(k, start, used):
            if start > n:
                return False
            if k == m:
                return True
            if used:
                return start <= S[k]
            return n - start >= m - k

        res = []
        prev = -1
        used = False
        for k in range(m):
            c = word2[k]
            j = prev + 1
            if j < n:
                if word1[j] == c:
                    if feas(k + 1, j + 1, used):
                        res.append(j)
                        prev = j
                        continue
                else:
                    if (not used) and feas(k + 1, j + 1, True):
                        res.append(j)
                        prev = j
                        used = True
                        continue
            # exact match at next occurrence > j
            i = j + 1
            while i < n and word1[i] != c:
                i += 1
            if i < n and feas(k + 1, i + 1, used):
                res.append(i)
                prev = i
                continue
            return []
        return res

