@st.composite
def gen(draw):
    n = draw(st.integers(2, 8))
    alphabet = draw(st.sampled_from(["ab", "abc"]))
    word1 = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    m = draw(st.integers(1, n - 1))
    mode = draw(st.integers(0, 2))
    if mode == 0:
        # random word2 over the same alphabet
        word2 = draw(st.text(alphabet=alphabet, min_size=m, max_size=m))
    elif mode == 1:
        # word2 close to a subsequence of word1 (often almost-equal cases)
        idx = sorted(draw(st.lists(st.integers(0, n - 1), min_size=m, max_size=m, unique=True)))
        chars = [word1[i] for i in idx]
        pos = draw(st.integers(0, m - 1))
        chars[pos] = draw(st.sampled_from(list(alphabet)))
        word2 = "".join(chars)
    else:
        # edge: all-equal strings
        c = draw(st.sampled_from(list(alphabet)))
        word1 = c * n
        word2 = draw(st.sampled_from([c * m, "".join(draw(st.sampled_from(list(alphabet))) for _ in range(m))]))
    return json.dumps(word1) + "\n" + json.dumps(word2) + "\n"


