    except Exception:
        return False
    if not isinstance(w1, str) or not isinstance(w2, str):
        return False
    if not (1 <= len(w2) < len(w1) <= 3 * 10**5):
        return False
    if not all('a' <= ch <= 'z' for ch in w1 + w2):
